contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call play with an arbitrary amount 'amt' (we send amt wei)
    function run(uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        require(address(this).balance >= amt);

        // Observe pre-call values
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;

        // Perform the call and record whether it reverted
        bool reverted;
        c.play{value: amt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe post-call values
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;

        // General rule: if the call did not revert and the sent amount equals the ticket price,
        // then the bank address remains unchanged and the pot either increases exactly by the ticket
        // amount or becomes zero.
        assert(reverted || amt != 10 || (bank_after == bank_before && (pot_after == pot_before + 10 || pot_after == 0)));
    }

    receive() external payable { }
}

