pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amt);
        uint256 pot_before;
        try c.pot() returns (uint256 __r) { pot_before = __r; } catch { return; }
        address bank_before;
        try c.bank() returns (address __r) { bank_before = __r; } catch { return; }
        bool reverted;
        try c.play{value: amt}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 pot_after;
        try c.pot() returns (uint256 __r) { pot_after = __r; } catch { return; }
        address bank_after;
        try c.bank() returns (address __r) { bank_after = __r; } catch { return; }
        assertTrue(reverted || amt != 10 || (bank_after == bank_before && (pot_after == pot_before + 10 || pot_after == 0)));
    }

    function testFuzz_run(uint256 amt) public {
        _run(amt);
    }

    receive() external payable { }
}
